// The mock webhook receives the exact JSON Meta sends to a real WhatsApp webhook.
// Unwrap it to the same shape the real WhatsApp Trigger node outputs.
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
if (!value) {
  throw new Error('Payload is not in WhatsApp webhook format. See test-mock.sh for examples.');
}
return [{ json: value }];

// Turns the fixtures + squads sheets into compact text for the AI
// Tournament details: edit these two lines for your own event
const TOURNAMENT_NAME = 'Junior Champions T20 Cup 2026';
const FORMAT = 'T20 (20 overs per side)';

const msg = $('Extract Question').first().json;
const fixtures = $('Read Fixtures').all().map(i => i.json);
const squads = $('Read Squads').all().map(i => i.json);

const fixtureText = fixtures.map(f =>
  `Match ${f['Match No']}: ${f['Team A']} vs ${f['Team B']} | Date: ${f['Date']} | Time: ${f['Time']} | Venue: ${f['Venue']} | Stage: ${f['Stage'] || 'League'} | Format: ${f['Format'] || 'T20'}`
).join('\n');

const squadText = squads.map(s =>
  `${s['Team']}: ${s['Players']}`
).join('\n');

const system = `You are the friendly help desk of a cricket academy that is running the ${TOURNAMENT_NAME}, an 8-team ${FORMAT} tournament.
Answer parents' questions ONLY using the tournament data below. Today's date is ${$now.toFormat('dd LLL yyyy')}.
Rules:
- Refer to the tournament as the ${TOURNAMENT_NAME}. Every match is ${FORMAT} unless the fixtures say otherwise.
- If a parent names a player, find that player's team in the squads, then answer about that team's matches.
- Keep answers short and WhatsApp friendly (max ~8 lines), use plain text, and include date, time and venue when relevant.
- If the answer is not in the data, say you don't have that information and ask them to contact the academy office.
- Never invent matches, times, venues or players.

FIXTURES:
${fixtureText}

SQUADS:
${squadText}`;

return [{ json: {
  from: msg.from,
  name: msg.name,
  question: msg.question,
  body: {
    model: 'claude-haiku-5-5',
    max_tokens: 500,
    system,
    messages: [{ role: 'user', content: `Parent ${msg.name} asks: ${msg.question}` }]
  }
}}];

